 async function createQuote(e:FormEvent){
  e.preventDefault();if(!customerId)return fail('Add a customer before creating a quotation.');if(!quoteLines.length)return fail('Add at least one quotation line.');
  const lines:Row[]=[];
  for(let index=0;index<quoteLines.length;index++){
   const line=quoteLines[index],item=catalogue.find(x=>x.id===line.catalogueItemId);if(!item)return fail('Select an active catalogue item for line '+(index+1)+'.');
   const quantity=Number(line.quantity);if(!Number.isInteger(quantity)||quantity<1)return fail('Line '+(index+1)+': quantity must be a whole number of at least 1.');
   if(item.standard_unit_price==null||!Number.isFinite(Number(item.standard_unit_price))||Number(item.standard_unit_price)<0)return fail('Line '+(index+1)+': this catalogue item has no owner-approved standard price.');
   if(item.selling_method==='quantity_tier')return fail('Line '+(index+1)+': quantity-tier pricing is not yet configured for server-side calculation.');
   if(item.selling_method!=='fixed_price'&&(!line.profileId||!profiles.some(p=>p.id===line.profileId)))return fail('Line '+(index+1)+': the selected catalogue method must have an active linked costing profile.');
   if(line.discountType!=='none'&&(!Number.isFinite(Number(line.discountValue))||Number(line.discountValue)<=0||!line.discountReason.trim()))return fail('Line '+(index+1)+': a discretionary discount requires a value and reason.');
   const methods=(item.catalogue_item_methods||[]).filter((m:Row)=>m.is_active);if(methods.length&&!methods.some((m:Row)=>m.production_method===line.productionMethod))return fail('Line '+(index+1)+': select an available production method.');
   lines.push({catalogue_item_id:item.id,description:item.name,production_method:line.productionMethod||null,costing_profile_id:line.profileId||null,quantity,supply_arrangement:line.supplyArrangement,discount_type:line.discountType,discount_value:Number(line.discountValue||0),discount_reason:line.discountReason.trim()||null,blank_cost_per_piece:line.blankCostPerPiece===''?null:Number(line.blankCostPerPiece),other_costs_total:Number(line.otherCosts||0),other_costs_note:line.otherCostsNote||''});
  }
  const allow=exception&&exceptionReason.trim().length>=8;if(exception&&!allow)return fail('Below-floor exception reason must contain at least 8 characters.');
  const saved=await rpc('owner_create_accepted_quotation',{p_customer_id:customerId,p_quote_number:quoteNo,p_valid_until:validUntil,p_allow_below_floor:allow,p_exception_reason:allow?exceptionReason:null,p_lines:lines},'Fully accepted quotation saved with '+lines.length+' line(s); server-side costing and margin validation completed.');if(!saved)return;
  setQuoteNo(nextNumber('Q'));setException(false);setExceptionReason('');setQuoteLines([{catalogueItemId:'',productionMethod:'',profileId:'',quantity:'1',supplyArrangement:'mj_supplies',discountType:'none',discountValue:'0',discountReason:'',blankCostPerPiece:'',otherCosts:'0',otherCostsNote:''}]);
 }
