 async function issueMaterial(){if(!selectedMaterial)return fail('Choose a job material first.');const material=jobMaterials.find(x=>x.id===selectedMaterial);if(!material)return fail('Choose a material planned for the selected production job.');const remaining=Number(material.planned_quantity||0)-Number(material.issued_quantity||0);const quantity=Number(issueQty);const available=Number(stock.find(x=>x.id===material.stock_item_id)?.quantity_on_hand||0);if(!Number.isFinite(quantity)||quantity<=0)return fail('Issue quantity must be greater than zero.');if(quantity>remaining)return fail('Issue quantity cannot exceed the remaining planned quantity.');if(quantity>available)return fail('Issue quantity cannot exceed available stock.');await rpc('owner_issue_job_material',{p_job_material_id:selectedMaterial,p_quantity:quantity},'Material issued and stock movement recorded.');setIssueQty('');}
 async function createSupplier(e:FormEvent){e.preventDefault();if(supplierName.trim().length<2)return fail('Supplier name must contain at least 2 characters.');await rpc('owner_create_supplier',{p_supplier_name:supplierName.trim(),p_phone:supplierPhone||null,p_email:supplierEmail||null,p_notes:supplierNotes||null},'Supplier saved.');setSupplierName('');setSupplierPhone('');setSupplierEmail('');setSupplierNotes('');}
 async function createPO(e:FormEvent){e.preventDefault();const lines=purchaseLines.map(line=>({stock_item_id:line.stockItemId,quantity:Number(line.quantity),unit_cost:Number(line.unitCost)}));if(!supplierId)return fail('Choose a supplier.');if(!poNumber.trim())return fail('Enter a purchase order number.');if(!lines.length||lines.some(line=>!line.stock_item_id||!Number.isFinite(line.quantity)||line.quantity<=0||!Number.isFinite(line.unit_cost)||line.unit_cost<0))return fail('Each purchase line needs a stock item, a positive quantity and a non-negative unit cost.');const transportCost=Number(transport);if(!Number.isFinite(transportCost)||transportCost<0)return fail('Transport cost must be zero or greater.');await rpc('owner_create_purchase_order',{p_supplier_id:supplierId,p_po_number:poNumber.trim(),p_transport_cost:transportCost,p_lines:lines},'Purchase order created. Stock will increase only as goods are received.');setPoNumber(nextNumber('PO'));setPurchaseLines([{stockItemId:stock[0]?.id||'',quantity:'1',unitCost:'0'}]);setTransport('0');}
 async function receivePO(line:Row){const remaining=Math.max(0,Number(line.quantity)-Number(line.received_quantity));const received=Number(receiptQuantities[line.id]??remaining);if(!line.stock_item_id)return fail('This purchase line is not linked to an inventory item and cannot be received automatically.');if(!Number.isFinite(received)||received<=0)return fail('Receipt quantity must be greater than zero.');if(received>remaining)return fail('Receipt quantity cannot exceed the outstanding quantity.');await rpc('owner_receive_purchase_order_line',{p_line_id:line.id,p_received_quantity:received},'Goods received and the stock ledger updated.');setReceiptQuantities(current=>({...current,[line.id]:''}));}
 async function recordPayment(e:FormEvent){e.preventDefault();const amount=Number(paymentAmount);const balance=Number(selectedInvoice?.balance||0);if(!payInvoice||!selectedInvoice)return fail('Choose an outstanding invoice first.');if(!Number.isFinite(amount)||amount<=0)return fail('Payment amount must be greater than zero.');if(amount>balance)return fail('Payment cannot exceed the outstanding invoice balance.');await rpc('owner_record_payment',{p_invoice_id:payInvoice,p_payment_number:paymentNumber,p_method:paymentMethod,p_amount:amount,p_reference_code:paymentRef||null},'Payment recorded and allocated to the invoice.');setPaymentNumber(nextNumber('PAY'));setPaymentRef('');}
 async function recordExpense(e:FormEvent){e.preventDefault();await rpc('owner_record_expense',{p_category:expenseCategory,p_description:expenseDescription,p_amount:Number(expenseAmount),p_payment_method:expenseMethod,p_expense_date:today()},'Expense recorded.');setExpenseDescription('');setExpenseAmount('');}
 async function recordDeposit(e:FormEvent){e.preventDefault();const amount=Number(depositAmount);if(!depositQuote||!selectedDepositQuote)return fail('Choose a sent or accepted quotation first.');if(!Number.isFinite(amount)||amount<=0)return fail('Deposit amount must be greater than zero.');if(amount>selectedDepositRemaining)return fail('Deposit cannot exceed the remaining quotation balance.');await rpc('owner_record_quote_deposit',{p_quote_id:depositQuote,p_deposit_number:depositNumber,p_method:depositMethod,p_amount:amount,p_reference_code:depositRef||null},'Quotation deposit recorded. It will be allocated automatically when the quote becomes an invoice.');setDepositNumber(nextNumber('DEP'));setDepositAmount('');setDepositRef('');}
 async function recordSupplierPayment(e:FormEvent){e.preventDefault();const amount=Number(supplierPayAmount);if(!supplierPayId)return fail('Choose a supplier.');if(!Number.isFinite(amount)||amount<=0)return fail('Payment amount must be greater than zero.');if(amount>selectedSupplierPayable)return fail('Supplier payment cannot exceed the outstanding balance.');await rpc('owner_record_supplier_payment',{p_supplier_id:supplierPayId,p_purchase_order_id:supplierPayOrder||null,p_payment_number:supplierPayNumber,p_method:supplierPayMethod,p_amount:amount,p_reference_code:supplierPayRef||null},'Supplier payment recorded in the append-only payment ledger.');setSupplierPayNumber(nextNumber('SPAY'));setSupplierPayAmount('');setSupplierPayRef('');}
 async function markPriceReviewed(a:Row){await rpc('owner_review_supplier_price_change',{p_supplier_id:a.supplier_id,p_stock_item_id:a.stock_item_id,p_previous_line_id:a.previous_line_id,p_latest_line_id:a.latest_line_id},'Supplier price change marked as reviewed.');}
 async function recordRefund(e:FormEvent){e.preventDefault();await rpc('owner_record_refund',{p_payment_id:refundPayment,p_amount:Number(refundAmount),p_reason:refundReason},'Refund request recorded separately from the original payment.');setRefundAmount('');setRefundReason('');}
 async function postRefund(id:string){await rpc('owner_post_refund',{p_refund_id:id},'Refund marked as paid/posted. The original payment remains unchanged.');}
 async function adjustInventory(e:FormEvent){e.preventDefault();const delta=Number(adjustDelta);const item=rows.find(s=>s.id===adjustStock);if(!item)return fail('Choose a stock item to adjust.');if(!Number.isFinite(delta)||delta===0)return fail('Enter a non-zero quantity change.');if(String(adjustReason).trim().length<5)return fail('Give a reason of at least 5 characters.');if(Number(item.quantity_on_hand)+delta<0)return fail('This adjustment would make stock negative.');await rpc('owner_adjust_inventory',{p_stock_item_id:adjustStock,p_quantity_delta:delta,p_reason:adjustReason.trim()},'Inventory adjustment recorded with an audit reason.');setAdjustDelta('');setAdjustReason('');}

