 const depositTotals=useMemo(()=>{const totals:Record<string,number>={};for(const d of quoteDeposits)totals[d.quotation_id]=(totals[d.quotation_id]||0)+Number(d.amount||0);return totals},[quoteDeposits]);
 const selectedDepositQuote=rows.find(q=>q.id===depositQuote);
